Load the cached values from Sheet4 and CBtrans, build normalized `(company, account, xchar)` keys from CBtrans, and test Sheet4 rows 2–7 against that set. Write the resulting `Match`/`-` values into K2:K7, apply the requested `#FF66CC` fill, and save the workbook. This produces the final 3-way match values without relying on the original formula.

```python
import shutil
import openpyxl
from openpyxl.styles import PatternFill

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

def norm_text(v):
    if v is None:
        return None
    s = str(v).strip()
    return s.casefold() if s else None

def as_number(v):
    if v is None or isinstance(v, bool):
        return None
    if isinstance(v, (int, float)):
        f = float(v)
    else:
        s = str(v).strip().replace(",", "")
        if not s:
            return None
        try:
            f = float(s)
        except Exception:
            return None
    if abs(f - round(f)) < 1e-9:
        return int(round(f))
    return round(f, 9)

def norm_company(v):
    n = as_number(v)
    if n is not None:
        return n
    return norm_text(v)

cb = vals["CBtrans"]
keys = set()

for row in cb.iter_rows(min_row=2, values_only=True):
    if not row:
        continue
    company = row[0] if len(row) > 0 else None
    account = row[7] if len(row) > 7 else None
    xchar = row[10] if len(row) > 10 else None

    key = (norm_company(company), norm_text(account), as_number(xchar))
    if all(x is not None for x in key):
        keys.add(key)

ws_vals = vals["Sheet4"]
ws = wb["Sheet4"]
fill = PatternFill(fill_type="solid", start_color="FF66CC", end_color="FF66CC")

results = []
for r in range(2, 8):
    company = ws_vals.cell(row=r, column=2).value
    account = ws_vals.cell(row=r, column=9).value
    xchar = ws_vals.cell(row=r, column=5).value

    key = (norm_company(company), norm_text(account), as_number(xchar))
    value = "Match" if key in keys else "-"

    cell = ws.cell(row=r, column=11)
    cell.value = value
    cell.fill = fill
    results.append(value)

print("CBtrans keys:", len(keys))
print("K2:K7:", results)

wb.save(OUT)
